/**
 * Lightweight Offline Chart Engine for modeloINV Dashboard.
 * Implements the core Chart.js v4 API for line, bar, and doughnut charts
 * completely offline with zero external dependencies.
 */
(function(global) {
    if (global.Chart) return;

    class Chart {
        constructor(ctx, config) {
            if (typeof ctx === 'string') {
                this.canvas = document.getElementById(ctx);
            } else if (ctx && ctx.getContext) {
                this.canvas = ctx;
            } else if (ctx && ctx.canvas) {
                this.canvas = ctx.canvas;
            } else {
                throw new Error("Invalid canvas context");
            }
            this.ctx = this.canvas.getContext('2d');
            this.config = config || {};
            this.type = this.config.type || 'line';
            this.data = this.config.data || { labels: [], datasets: [] };
            this.options = this.config.options || {};
            this.animationFrame = null;

            this._handleResize = () => this.render();
            window.addEventListener('resize', this._handleResize);
            this.render();
        }

        destroy() {
            if (this._handleResize) {
                window.removeEventListener('resize', this._handleResize);
            }
        }

        update() {
            this.render();
        }

        render() {
            if (!this.canvas || !this.ctx) return;
            const dpr = window.devicePixelRatio || 1;
            const rect = this.canvas.getBoundingClientRect();
            const width = rect.width || this.canvas.width || 400;
            const height = rect.height || this.canvas.height || 220;

            this.canvas.width = width * dpr;
            this.canvas.height = height * dpr;
            this.ctx.resetTransform ? this.ctx.resetTransform() : this.ctx.setTransform(1, 0, 0, 1, 0, 0);
            this.ctx.scale(dpr, dpr);

            this.ctx.clearRect(0, 0, width, height);

            if (this.type === 'doughnut') {
                this._renderDoughnut(width, height);
            } else {
                this._renderCartesian(width, height);
            }
        }

        _renderDoughnut(w, h) {
            const ctx = this.ctx;
            const ds = (this.data.datasets && this.data.datasets[0]) || { data: [] };
            const data = ds.data || [];
            const colors = ds.backgroundColor || ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#64748b'];
            const total = data.reduce((a, b) => a + b, 0);

            const cx = w * 0.42;
            const cy = h * 0.5;
            const radius = Math.min(cx, cy) * 0.78;
            const innerRadius = radius * 0.60;

            let startAngle = -Math.PI / 2;

            if (total <= 0) {
                ctx.beginPath();
                ctx.arc(cx, cy, radius, 0, Math.PI * 2);
                ctx.arc(cx, cy, innerRadius, Math.PI * 2, 0, true);
                ctx.fillStyle = '#334155';
                ctx.fill();
            } else {
                for (let i = 0; i < data.length; i++) {
                    const sliceAngle = (data[i] / total) * Math.PI * 2;
                    ctx.beginPath();
                    ctx.arc(cx, cy, radius, startAngle, startAngle + sliceAngle);
                    ctx.arc(cx, cy, innerRadius, startAngle + sliceAngle, startAngle, true);
                    ctx.closePath();
                    ctx.fillStyle = colors[i % colors.length];
                    ctx.fill();
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = '#0f172a';
                    ctx.stroke();
                    startAngle += sliceAngle;
                }
            }

            // Legend
            const labels = this.data.labels || [];
            const lx = w * 0.72;
            let ly = h * 0.22;
            ctx.font = '11px sans-serif';
            ctx.textAlign = 'left';

            for (let i = 0; i < labels.length; i++) {
                ctx.fillStyle = colors[i % colors.length];
                ctx.fillRect(lx, ly - 8, 10, 10);
                ctx.fillStyle = '#cbd5e1';
                const pct = total > 0 && data[i] !== undefined ? ` (${Math.round((data[i] / total) * 100)}%)` : '';
                ctx.fillText(`${labels[i]}${pct}`, lx + 16, ly);
                ly += 22;
            }
        }

        _renderCartesian(w, h) {
            const ctx = this.ctx;
            const padLeft = 45;
            const padRight = 15;
            const padTop = 18;
            const padBottom = 28;
            const plotW = w - padLeft - padRight;
            const plotH = h - padTop - padBottom;

            const labels = this.data.labels || [];
            const datasets = this.data.datasets || [];

            // Calculate min / max values
            let minVal = Infinity;
            let maxVal = -Infinity;

            datasets.forEach(ds => {
                (ds.data || []).forEach(val => {
                    if (val !== null && val !== undefined) {
                        if (val < minVal) minVal = val;
                        if (val > maxVal) maxVal = val;
                    }
                });
            });

            if (minVal === Infinity || maxVal === -Infinity) {
                minVal = 0;
                maxVal = 100;
            }
            if (minVal === maxVal) {
                minVal -= 1;
                maxVal += 1;
            }

            const range = maxVal - minVal;
            const padding = range * 0.08;
            const yMin = minVal - padding;
            const yMax = maxVal + padding;
            const yRange = yMax - yMin;

            // Draw grid lines
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            const gridLines = 4;
            ctx.font = '10px monospace';
            ctx.fillStyle = '#64748b';
            ctx.textAlign = 'right';

            for (let i = 0; i <= gridLines; i++) {
                const y = padTop + (plotH / gridLines) * i;
                ctx.beginPath();
                ctx.moveTo(padLeft, y);
                ctx.lineTo(padLeft + plotW, y);
                ctx.stroke();

                const val = yMax - (yRange / gridLines) * i;
                ctx.fillText(val.toFixed(val < 10 && val > -10 ? 2 : 1), padLeft - 6, y + 3);
            }

            // Draw X labels
            ctx.textAlign = 'center';
            const xSteps = Math.min(labels.length, 6);
            if (labels.length > 1) {
                for (let i = 0; i < xSteps; i++) {
                    const idx = Math.floor((i / (xSteps - 1)) * (labels.length - 1));
                    const x = padLeft + (idx / (labels.length - 1)) * plotW;
                    ctx.fillText(labels[idx], x, h - 8);
                }
            } else if (labels.length === 1) {
                ctx.fillText(labels[0], padLeft + plotW / 2, h - 8);
            }

            // Draw datasets
            datasets.forEach(ds => {
                const data = ds.data || [];
                if (data.length === 0) return;

                const color = ds.borderColor || ds.backgroundColor || '#3b82f6';
                ctx.strokeStyle = color;
                ctx.lineWidth = ds.borderWidth || 2;

                const points = [];
                for (let i = 0; i < data.length; i++) {
                    const x = labels.length > 1 ? padLeft + (i / (labels.length - 1)) * plotW : padLeft + plotW / 2;
                    const y = padTop + plotH - ((data[i] - yMin) / yRange) * plotH;
                    points.push({ x, y });
                }

                if (points.length > 0) {
                    ctx.beginPath();
                    ctx.moveTo(points[0].x, points[0].y);
                    for (let i = 1; i < points.length; i++) {
                        ctx.lineTo(points[i].x, points[i].y);
                    }
                    ctx.stroke();

                    // Optional fill
                    if (ds.fill && points.length > 1) {
                        ctx.lineTo(points[points.length - 1].x, padTop + plotH);
                        ctx.lineTo(points[0].x, padTop + plotH);
                        ctx.closePath();
                        ctx.fillStyle = ds.backgroundColor || 'rgba(59, 130, 246, 0.15)';
                        ctx.fill();
                    }

                    // Dots on endpoints
                    if (points.length > 0) {
                        const last = points[points.length - 1];
                        ctx.beginPath();
                        ctx.arc(last.x, last.y, 3, 0, Math.PI * 2);
                        ctx.fillStyle = color;
                        ctx.fill();
                    }
                }
            });

            // Small dataset legend
            ctx.textAlign = 'left';
            let legX = padLeft;
            datasets.forEach(ds => {
                const color = ds.borderColor || ds.backgroundColor || '#3b82f6';
                ctx.fillStyle = color;
                ctx.fillRect(legX, 4, 8, 8);
                ctx.fillStyle = '#94a3b8';
                ctx.fillText(ds.label || '', legX + 12, 11);
                legX += ctx.measureText(ds.label || '').width + 24;
            });
        }
    }

    global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
